    if (value === undefined) return []
    if (!Array.isArray(value)) throw fail(`Invalid ${fieldName} list in ${source}`, 'invalid-list', source, fieldName)

    return value.map((entry, index) => requireIdentity(entry, `${fieldName}[${index}]`, source))
